cd /workspace/bjj-journal
{ echo '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>BJJ Principles Journal</title><style>'; cat app.css; echo '</style></head><body><main></main><div class="sheetbg" id="sbg"></div><div class="sheet" id="sheet" role="dialog"></div><nav><button data-t="today">Today</button><button data-t="principles">Principles</button><button data-t="history">History</button></nav><script>'; grep -v '^const ICON\|^[0-9]*:.<\|^// Journal.s own hand' data.js | sed 's/,icon:ICON\[n\]//'; cat chains.js app.js; echo '</script></body></html>'; } > index.html
